use crate::{files::{args,path,text},text_tools::{boolean,number}};
use serde_json::{json,Value};
use std::{collections::BTreeMap,io::{BufRead,BufReader,Read,Write},os::unix::{io::AsRawFd,net::UnixStream,process::CommandExt},process::{Child,ChildStdin,Command,Stdio},sync::{mpsc,Arc,Mutex},time::{Duration,Instant}};
const OUTPUT_LIMIT:usize=1024*1024;
#[derive(Default)]struct Output{bytes:Vec<u8>,discarded:usize}
impl Output{fn take(&mut self)->(String,bool){let s=String::from_utf8_lossy(&self.bytes).into_owned();let t=self.discarded>0;self.bytes.clear();self.discarded=0;(s,t)}}
fn drain<R:Read+Send+'static>(mut r:R,out:Arc<Mutex<Output>>){std::thread::spawn(move||{let mut b=[0;8192];loop{let n=match r.read(&mut b){Ok(0)|Err(_)=>break,Ok(n)=>n};let mut o=out.lock().unwrap();let keep=n.min(OUTPUT_LIMIT.saturating_sub(o.bytes.len()));o.bytes.extend_from_slice(&b[..keep]);o.discarded+=n-keep;}});}
fn quote(s:&str)->String{format!("'{}'",s.replace('\'',"'\\''"))}
fn kill(c:&mut Child){unsafe{libc::kill(-(c.id() as i32),libc::SIGKILL);}let _=c.wait();}
struct Shell{child:Child,input:ChildStdin,records:mpsc::Receiver<Vec<u8>>,output:Arc<Mutex<Output>>}
impl Shell{fn new(state:&str,cwd:&str)->Result<Self,String>{let(a,b)=UnixStream::pair().map_err(|e|e.to_string())?;let fd=b.as_raw_fd();let mut cmd=Command::new("bash");cmd.args(["--noprofile","--norc"]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).process_group(0);unsafe{cmd.pre_exec(move||{if libc::dup2(fd,3)<0{return Err(std::io::Error::last_os_error());}if libc::fcntl(3,libc::F_SETFD,0)<0{return Err(std::io::Error::last_os_error());}Ok(())});}let mut child=cmd.spawn().map_err(|e|e.to_string())?;drop(b);let mut input=child.stdin.take().unwrap();let output=Arc::new(Mutex::new(Output::default()));drain(child.stdout.take().unwrap(),output.clone());drain(child.stderr.take().unwrap(),output.clone());let(tx,rx)=mpsc::channel();std::thread::spawn(move||{let mut r=BufReader::new(a);loop{let mut b=Vec::new();if r.read_until(0,&mut b).unwrap_or(0)==0{break;}b.pop();if tx.send(b).is_err(){break;}}});if !state.is_empty(){writeln!(input,"eval {}; cd -- {}",quote(state),quote(cwd)).map_err(|e|e.to_string())?;}Ok(Self{child,input,records:rx,output})}}
impl Drop for Shell{fn drop(&mut self){kill(&mut self.child);}}
struct Job{child:Child,input:Option<ChildStdin>,output:Arc<Mutex<Output>>,code:Option<i32>,command:String}
impl Drop for Job{fn drop(&mut self){kill(&mut self.child);}}
pub struct Terminal{shell:Option<Shell>,jobs:BTreeMap<String,Job>,next:u64,state:String,cwd:String}
impl Terminal{
 pub fn new()->Self{Self{shell:None,jobs:BTreeMap::new(),next:0,state:String::new(),cwd:std::env::current_dir().unwrap_or_default().to_string_lossy().into_owned()}}
 pub fn run(&mut self,v:&Value)->Result<Value,String>{args(v,&["command","workdir","timeout","background","pty"])?;let background=boolean(v,"background")?;if !background&&v.get("workdir").is_some_and(|w|!w.is_null()){return Err("foreground workdir is unsupported; use an explicit cd in the command (which changes the persistent shell), or use background=true with workdir".into());}if boolean(v,"pty")?{return Err("PTY is unsupported by standalone receiver; use a normal background pipe".into());}let command=text(v,"command")?;let timeout=number(v,"timeout",180,1800)?;if timeout==0{return Err("timeout must be positive".into());}let cwd=if let Some(w)=v.get("workdir").filter(|x|!x.is_null()){Some(path(w.as_str().ok_or("workdir must be string")?)?)}else{None};
 let run=format!("{{ eval {}; }} </dev/null",quote(command));
 if let Some(w)=&cwd{if !w.is_dir(){return Err(format!("workdir is not a directory: {}",w.display()));}}
 if background{let job_cwd=cwd.unwrap_or_else(||self.cwd.clone().into()).canonicalize().map_err(|e|format!("cannot resolve background workdir: {e}"))?;let mut cmd=Command::new("bash");let mut script=format!("eval {}",quote(command));if !self.state.is_empty(){script=format!("{}\n{}",self.state,script);}cmd.args(["--noprofile","--norc","-c",&script]).current_dir(&job_cwd).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).process_group(0);let mut child=cmd.spawn().map_err(|e|e.to_string())?;let output=Arc::new(Mutex::new(Output::default()));drain(child.stdout.take().unwrap(),output.clone());drain(child.stderr.take().unwrap(),output.clone());self.next+=1;let id=format!("job-{}",self.next);let pid=child.id();let input=child.stdin.take();self.jobs.insert(id.clone(),Job{child,input,output,code:None,command:command.into()});return Ok(json!({"session_id":id,"pid":pid,"status":"running","cwd":job_cwd}));}
 if self.shell.is_none(){self.shell=Some(Shell::new(&self.state,&self.cwd)?);}let shell=self.shell.as_mut().unwrap();if shell.child.try_wait().map_err(|e|e.to_string())?.is_some(){self.shell=None;return self.run(v);}shell.output.lock().unwrap().take();writeln!(shell.input,"{run}\n__teleoperator_code=$?; printf '%s\\0' \"$__teleoperator_code\" >&3; pwd -P >&3; printf '\\0' >&3; export -p >&3; printf '\\0' >&3").map_err(|e|e.to_string())?;shell.input.flush().map_err(|e|e.to_string())?;
 let deadline=Instant::now()+Duration::from_secs(timeout as u64);let mut records=Vec::new();let mut timed_out=false;for _ in 0..3{let wait=deadline.saturating_duration_since(Instant::now());match shell.records.recv_timeout(wait){Ok(r)=>records.push(r),Err(mpsc::RecvTimeoutError::Timeout)=>{timed_out=true;break;},Err(_)=>{break;}}}
 if timed_out||records.len()!=3{kill(&mut shell.child);}std::thread::sleep(Duration::from_millis(20));let(output,truncated)=shell.output.lock().unwrap().take();let code=records.first().and_then(|b|std::str::from_utf8(b).ok()).and_then(|s|s.parse::<i32>().ok());if records.len()==3{self.cwd=String::from_utf8_lossy(&records[1]).trim_end_matches(['\n','\r']).to_string();self.state=String::from_utf8_lossy(&records[2]).into_owned();}else{self.shell.take();}Ok(json!({"output":output,"exit_code":code,"timed_out":timed_out,"truncated":truncated,"cwd":self.cwd,"shell_reset":records.len()!=3}))}
 pub fn manage(&mut self,v:&Value)->Result<Value,String>{args(v,&["action","session_id","timeout","data","text"])?;let action=text(v,"action")?;if action=="list"{if v.as_object().unwrap().len()!=1{return Err("list accepts only action".into());}let mut rows=Vec::new();for(id,j)in &mut self.jobs{update(j)?;rows.push(json!({"session_id":id,"pid":j.child.id(),"command":j.command,"status":if j.code.is_some(){"exited"}else{"running"},"exit_code":j.code}));}return Ok(json!({"sessions":rows}));}let id=text(v,"session_id")?;let j=self.jobs.get_mut(id).ok_or("Unknown session_id")?;
 match action{"status"|"poll"=>{args(v,&["action","session_id"])?;update(j)?;},"wait"=>{args(v,&["action","session_id","timeout"])?;let end=Instant::now()+Duration::from_secs(number(v,"timeout",30,1800)? as u64);loop{update(j)?;if j.code.is_some()||Instant::now()>=end{break;}std::thread::sleep(Duration::from_millis(10));}},"kill"=>{args(v,&["action","session_id"])?;kill(&mut j.child);update(j)?;},"write"|"submit"=>{args(v,&["action","session_id","data","text"])?;if v.get("data").is_some()&&v.get("text").is_some(){return Err("Use data or text, not both".into());}let data=v.get("data").or_else(||v.get("text")).and_then(Value::as_str).ok_or("data or text must be a string")?;let input=j.input.as_mut().ok_or("Job stdin is closed")?;input.write_all(data.as_bytes()).and_then(|_|if action=="submit"{input.write_all(b"\n")}else{Ok(())}).and_then(|_|input.flush()).map_err(|e|e.to_string())?;},_=>return Err(format!("Unsupported process action: {action}"))}
 std::thread::sleep(Duration::from_millis(10));let(output,truncated)=if action=="status"||action=="write"||action=="submit"{(String::new(),false)}else{j.output.lock().unwrap().take()};Ok(json!({"session_id":id,"pid":j.child.id(),"status":if j.code.is_some(){"exited"}else{"running"},"exit_code":j.code,"output":output,"truncated":truncated}))}
}
fn update(j:&mut Job)->Result<(),String>{if j.code.is_none(){if let Some(s)=j.child.try_wait().map_err(|e|e.to_string())?{use std::os::unix::process::ExitStatusExt;j.code=Some(s.code().unwrap_or_else(||128+s.signal().unwrap_or(0)));j.input.take();}}Ok(())}
